import { ChangeDetectionStrategy, Component, computed, inject, input } from '@angular/core';
import { Params, UrlSerializer } from '@angular/router';
import { NavigationService } from 'espd-common/navigation';

@Component({
	selector: 'espd-breadcrumb',
	templateUrl: './breadcrumb.component.html',
	styleUrl: './breadcrumb.component.scss',
	changeDetection: ChangeDetectionStrategy.OnPush,
	host: {
		'[attr.role]': 'listitem',
		'[attr.aria-current]': 'this.active() ? "page" : null',
		'class': 'breadcrumb-item',
		'[class.active]': 'this.active()'
	},
	standalone: false
})
export class BreadcrumbComponent {

	private navigationService = inject(NavigationService);
	private urlSerializer = inject(UrlSerializer);

	public link = input('');
	public href = input('');
	public active = input(false)
	public queryParams = computed<Params | null>(() => this.linkUrlTree()?.queryParams || null);
	public route = computed<string>(() =>
		'/' + (this.linkUrlTree()?.root.children.primary?.toString() || '')
	);

	private linkUrlTree = computed(() => {
		if (this.link()) {
			const previousPath = this.navigationService.findPastRoute(this.link());
			return this.urlSerializer.parse(previousPath);
		} else {
			return null;
		}
	});
}